import com.smartmanager.nativeapp.*;import java.util.*;
public class BatchReconciliationMockTest {
 public static void main(String[] args){String r=RouterIdentity.of("Router.local",8728,"admin",false);if(!r.equals(RouterIdentity.of("router.LOCAL",8728,"admin",false)))throw new AssertionError("identity");BatchLedger l=new BatchLedger();l.addPending(r,"SM0000001","123456","basic");l.addPending(r,"SM0000002","654321","basic");l.mark(r,"SM0000002",BatchLedger.State.UNKNOWN);List<Map<String,String>> users=new ArrayList<>();Map<String,String> u=new HashMap<>();u.put("name","SM0000001");u.put("profile","basic");users.add(u);if(BatchReconciler.reconcile(l,r,users)!=1)throw new AssertionError("found");if(l.find(r,"SM0000001").state!=BatchLedger.State.CONFIRMED||l.find(r,"SM0000002").state!=BatchLedger.State.UNKNOWN)throw new AssertionError("states");try{l.addPending(r,"SM0000001","x","basic");throw new AssertionError("duplicate add");}catch(IllegalArgumentException ok){}try{BatchReconciler.reconcile(l,r,users,false,true);throw new AssertionError("incomplete accepted");}catch(IllegalStateException ok){}System.out.println("PASS: reconciliation preserves UNKNOWN, rejects incomplete reads, isolates router and prevents duplicate add");}
}
